const TAG_INFO=Object.freeze({新生:'改變出牌、行動或限制，讓玩家突破原本局勢。',流轉:'在玩家之間交換、給予或重新分配手牌。',洞察:'查看、篩選、搜尋或回收牌庫與棄牌區資訊。',庇護:'免疫、承受、解除或保護效果。',共鳴:'合作、指定他人或多人互動。',火種:'直接影響火種的獲得、轉移或經濟。',使命:'直接影響使命進度、條件或完成判定。',熄滅:'直接破壞火種經濟。',掠奪:'棄牌、奪牌、交換或破壞手牌結構。',重構:'改變出牌、行動或功能牌規則。',蔓延:'持續、傳染或延遲生效的效果。',崩解:'直接破壞場上、已出牌區或既有效果。',群體:'此效果會同時影響多名玩家。',單體:'此效果會指定一名玩家。',多體:'此效果會指定多名玩家。',應對:'在符合時機時可立即打出，且不占用一般行動。'});
const STRUCTURAL_TAGS=new Set(['應對','群體','單體','多體','負面']);
const TAG_FACE_FILES=Object.freeze({新生:'Rebirth',流轉:'Flux',洞察:'Insight',庇護:'Sanctuary',共鳴:'Resonance',火種:'Ember',使命:'Mission',重構:'Reforge',掠奪:'Plunder',熄滅:'Extinction',蔓延:'Spread',崩解:'Collapse'});

function qaFaceTag(definition){const query=new URLSearchParams(globalThis.location?.search??''),mode=query.get('qa'),tag=query.get('tag');if(mode==='tag-glyphs'||(mode==='tag-glyph'&&tag==='Ember')){if(definition.definitionId==='miracle-05')return '火種';}if(mode==='tag-glyphs'||(mode==='tag-glyph'&&tag==='Mission')){if(definition.definitionId==='miracle-09')return '使命';}return undefined;}
function faceTag(definition){return qaFaceTag(definition)??definition.tags?.find(value=>!STRUCTURAL_TAGS.has(value)&&TAG_FACE_FILES[value]);}
function tagFaceAsset(definition){if(!['miracle','disaster'].includes(definition.kind))return definition.image;const tag=faceTag(definition),file=TAG_FACE_FILES[tag];if(!file)return definition.image;const folder=definition.kind==='miracle'?'miracles':'disasters';const prefix=definition.kind==='miracle'?'miracal':'disater';const response=definition.tags?.includes('應對')?'-Response':'';return `assets/${folder}/${prefix}-${file}${response}.png`;}
function cardFaceMarkup(definition,title,className){return `<img class="${className}" draggable="false" src="${tagFaceAsset(definition)}" alt="${title}">`;}
const TAG_FACE_SVGS=Object.freeze({新生:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><rect x="23" y="23" width="54" height="54" rx="10" transform="rotate(45 50 50)"/></svg>',流轉:'<svg viewBox="0 0 100 100" fill="currentColor" fill-rule="evenodd" aria-hidden="true"><path fill-rule="evenodd" d="M50 15a35 35 0 1 0 0 70a35 35 0 1 0 0-70ZM50 35a15 15 0 1 1 0 30a15 15 0 1 1 0-30Z"/></svg>',熄滅:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><path d="M50 16C53 16 55 18 57 21L86 70C89 75 86 81 80 81H20C14 81 11 75 14 70L43 21C45 18 47 16 50 16Z" transform="rotate(180 50 50)"/></svg>',洞察:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><path d="M50 16C53 16 55 18 57 21L86 70C89 75 86 81 80 81H20C14 81 11 75 14 70L43 21C45 18 47 16 50 16Z"/></svg>',庇護:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><path d="M21 81C17 81 14 78 14 74V58C14 40 30 23 50 23C70 23 86 40 86 58V74C86 78 83 81 79 81H70C67 81 65 79 65 76V63C65 54 59 49 50 49C41 49 35 54 35 63V76C35 79 33 81 30 81H21Z"/></svg>',共鳴:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><circle cx="50" cy="50" r="31"/></svg>',火種:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><ellipse cx="50" cy="50" rx="28" ry="35"/></svg>',使命:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="M25 14H75Q86 14 86 25V75Q86 86 75 86H25Q14 86 14 75V25Q14 14 25 14ZM38 30H62Q70 30 70 38V62Q70 70 62 70H38Q30 70 30 62V38Q30 30 38 30Z"/></svg>',掠奪:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><rect x="15" y="17" width="20" height="66" rx="8"/><rect x="40" y="17" width="20" height="66" rx="8"/><rect x="65" y="17" width="20" height="66" rx="8"/></svg>',重構:'<svg viewBox="0 0 100 100" fill="currentColor" fill-rule="evenodd" aria-hidden="true"><path d="M50 8L83 41Q92 50 83 59L59 83Q50 92 41 83L17 59Q8 50 17 41L41 17Q50 8 59 17Z M50 36.4L61.4 47.8Q63.6 50 61.4 52.2L52.2 61.4Q50 63.6 47.8 61.4L38.6 52.2Q36.4 50 38.6 47.8L47.8 38.6Q50 36.4 52.2 38.6Z"/></svg>',蔓延:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><rect x="19" y="19" width="62" height="28" rx="8"/><rect x="19" y="53" width="62" height="28" rx="8"/></svg>',崩解:'<svg viewBox="0 0 100 100" fill="currentColor" aria-hidden="true"><rect x="19" y="19" width="62" height="62" rx="15"/></svg>'});
function primaryFaceTag(definition){const tag=faceTag(definition);return TAG_FACE_SVGS[tag]?tag:undefined;}
function faceGlyph(definition){const tag=primaryFaceTag(definition),svg=TAG_FACE_SVGS[tag];if(!svg||(definition.tags?.includes('應對')&&tag!=='新生'&&!['miracle-16','miracle-17','disaster-16'].includes(definition.definitionId)))return'';const tone=definition.kind==='disaster'?' is-disaster':'';return `<span class="runtime-tag-glyph runtime-tag-glyph--${TAG_FACE_FILES[tag]?.toLowerCase()??'generic'}${tone}" data-runtime-face-glyph data-runtime-face-tag="${tag}" aria-hidden="true">${svg}</span>`;}
let cardInspectorTimer=null;
function closeCardInspector(){const inspector=document.querySelector('#card-inspector'),content=document.querySelector('#card-inspector-content'),host=document.querySelector('#card-inspector-card');if(!inspector||inspector.hidden)return;clearTimeout(cardInspectorTimer);inspector.dataset.closing='true';content?.classList.remove('show');inspector.setAttribute('aria-hidden','true');cardInspectorTimer=setTimeout(()=>{if(inspector.dataset.closing==='true'){inspector.hidden=true;delete inspector.dataset.closing;content?.classList.remove('drag-mode');inspector.classList.remove('drag-mode');if(host)host.replaceChildren();}},210);}
function primaryInspectorTag(definition){return qaFaceTag(definition)??definition.tags?.find(tag=>!STRUCTURAL_TAGS.has(tag))??definition.tags?.[0]??(definition.kind==='resource'?'物資':names[definition.kind]);}
function setInspectorTab(target){const text=document.querySelector('#card-inspector-text');if(!text)return;text.querySelectorAll('.tab-btn').forEach(button=>{const active=button.dataset.target===target;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});text.querySelectorAll('.tab-pane').forEach(pane=>pane.classList.toggle('active',pane.id===target));}
function renderInspectorText(definition,title,{inEffectZone=false}={}){const text=document.querySelector('#card-inspector-text');if(!text)return;const tag=primaryInspectorTag(definition),buttons=text.querySelectorAll('.tab-btn'),effect=text.querySelector('#pane-effect p'),type=text.querySelector('#pane-type p');buttons[0].textContent=title;buttons[1].textContent=tag;effect.textContent=(inEffectZone?definition.effectText:undefined)??definition.text??`${title}的詳細資訊。`;type.textContent=TAG_INFO[tag]??`${tag}是這張牌的主要類型。`;setInspectorTab('pane-effect');}
function openCardInspector(card,{dragMode=false,inEffectZone=false}={}){const definition=getDefinition(card),title=definitionTitle(definition),inspector=document.querySelector('#card-inspector'),content=document.querySelector('#card-inspector-content'),host=document.querySelector('#card-inspector-card');if(!inspector||!content||!host)return;const wasOpen=!inspector.hidden&&!inspector.dataset.closing;clearTimeout(cardInspectorTimer);delete inspector.dataset.closing;const primaryTag=primaryFaceTag(definition),tag=definition.tags?.includes('應對')&&primaryTag!=='新生'&&!['miracle-16','miracle-17'].includes(definition.definitionId)?null:primaryTag;host.dataset.faceGlyph=tag??'';host.dataset.faceGlyphTone=definition.kind;host.innerHTML=`${cardFaceMarkup(definition,title,'detail-card-art')}${faceGlyph(definition)}`;const runtimeInspectorImage=host.querySelector('img.detail-card-art');if(runtimeInspectorImage)runtimeInspectorImage.dataset.runtimeInspectorFace='true';renderInspectorText(definition,title,{inEffectZone});inspector.hidden=false;inspector.setAttribute('aria-hidden','false');inspector.classList.toggle('drag-mode',dragMode);content.classList.toggle('drag-mode',dragMode);if(wasOpen){content.classList.add('show');return;}content.classList.remove('show');requestAnimationFrame(()=>{if(!inspector.hidden&&!inspector.dataset.closing)content.classList.add('show');});}
globalThis.__shepherdOpenCardInspector=openCardInspector;
globalThis.__shepherdCloseCardInspector=closeCardInspector;
globalThis.__shepherdCardFaceGlyph=faceGlyph;
globalThis.__shepherdCardFaceAsset=tagFaceAsset;
function setupCardInspector(){const inspector=document.querySelector('#card-inspector'),text=document.querySelector('#card-inspector-text'),reset=()=>{const card=inspector?.querySelector('.detail-foil-card');if(!card)return;card.style.setProperty('--foil-rx','0deg');card.style.setProperty('--foil-ry','0deg');card.style.setProperty('--foil-x','50%');card.style.setProperty('--foil-y','50%');},tilt=event=>{if(!inspector||inspector.hidden)return;const card=inspector.querySelector('.detail-foil-card');if(!card)return;const rect=card.getBoundingClientRect(),px=(event.clientX-rect.left)/rect.width,py=(event.clientY-rect.top)/rect.height;if(px<0||px>1||py<0||py>1){reset();return;}card.style.setProperty('--foil-rx',`${((.5-py)*18).toFixed(2)}deg`);card.style.setProperty('--foil-ry',`${((px-.5)*22).toFixed(2)}deg`);card.style.setProperty('--foil-x',`${(px*100).toFixed(1)}%`);card.style.setProperty('--foil-y',`${(py*100).toFixed(1)}%`);};if(!inspector)return;text?.addEventListener('click',event=>{const button=event.target.closest('.tab-btn');if(button)setInspectorTab(button.dataset.target);});document.addEventListener('pointermove',tilt,{passive:true});document.addEventListener('pointerdown',event=>{if(inspector.hidden)return;if(event.target.closest?.('button.card[data-card-id],#card-inspector-text'))return;closeCardInspector();});window.addEventListener('pointerup',()=>{if(inspector.classList.contains('drag-mode'))closeCardInspector();},{capture:true});window.addEventListener('blur',reset);}
setupCardInspector();
function resetTagDetailLayout(){const overlay=document.querySelector('#detail-overlay'),panel=overlay?.querySelector('.detail-panel'),content=overlay?.querySelector('#detail-content'),backdrop=overlay?.querySelector('.overlay-backdrop'),close=panel?.querySelector('.overlay-close');if(overlay){overlay.classList.remove('tag-detail-overlay');overlay.style.cssText='';}for(const element of [panel,content,backdrop])if(element)element.style.cssText='';if(close)close.hidden=false;}
function applyTagDetailLayout(){const overlay=document.querySelector('#detail-overlay'),panel=overlay?.querySelector('.detail-panel'),content=overlay?.querySelector('#detail-content'),backdrop=overlay?.querySelector('.overlay-backdrop'),close=panel?.querySelector('.overlay-close'),set=(element,styles)=>Object.entries(styles).forEach(([name,value])=>element.style.setProperty(name,value,'important'));if(!overlay||!panel||!content||!backdrop)return;overlay.classList.add('tag-detail-overlay');set(overlay,{display:'block','pointer-events':'none'});set(backdrop,{display:'none'});set(panel,{position:'fixed',left:'50%',top:'48%',transform:'translate(-50%,-50%)',width:'auto','min-height':'0',padding:'0',border:'0','border-radius':'0',background:'transparent','box-shadow':'none','backdrop-filter':'none',display:'block','pointer-events':'auto',overflow:'visible'});set(content,{display:'block',padding:'0',margin:'0',background:'transparent','border-top':'0',gap:'0'});if(close)set(close,{display:'none'});}

const names = { sheep: '群羊', food: '糧食', money: '金錢', grace: '恩典', miracle: '神蹟', disaster: '災難' };
const $ = (selector) => document.querySelector(selector);
let actions = [];
let token = null;
let currentState = null;
let selectedInstanceId = null;
let selectedBlindnessPile = null;
let drag = null;
let gracePending = null;
let lastPlayedId = null;
let lastJudgmentId = null;
let lastRevelationId = null;

const LONG_PRESS_MS = 480;
const DRAG_THRESHOLD = 6;
const isRebirthFacePreview = new URLSearchParams(globalThis.location?.search ?? '').get('qa') === 'rebirth-card-face';

function playerName(state, playerId) { const player=state?.players?.find(candidate=>candidate.playerId===playerId);if(!player)return playerId??'無';return player.type==='human'?'你':(player.displayName??`Player ${player.seat}`); }
function humanCanAct(){const human=currentState?.players?.[0];return Boolean(currentState&&human&&currentState.currentPlayer===human.playerId&&!currentState.gameOver&&!globalThis.__shepherdDecisionPending?.());}
function actionsForCard(card) { return actions.filter((action) => ['playResource', 'playMiracle'].includes(action.type) && action.instanceId === card.instanceId); }
function definitionTitle(definition) { if (definition.kind === 'miracle' || definition.kind === 'disaster') return definition.name; return `${names[definition.type]} ${definition.number}`; }
function transformedImage(definition, declaredType) { if (definition.kind !== 'resource' || definition.type !== 'grace' || !declaredType) return definition.image; return `assets/cards/${declaredType}-${definition.number}.png`; }
function cardStatus(card, state) { const definition=getDefinition(card),playableActions=actionsForCard(card),human=state.players[0],humanTurn=state.currentPlayer===human.playerId,orderJudgment=state.activeJudgments?.['秩序'];if(definition.kind==='miracle'||definition.kind==='disaster')return{definition,ruleLegal:true,playableActions,humanTurn,actionable:playableActions.length>0};const possible=definition.type==='grace'?RESOURCE_TYPES:[definition.type],ruleLegal=possible.some(type=>isLegalResourcePlay(card,state.currentResource,type,{reversed:['disorder-1','disorder-2'].includes(orderJudgment),invertedNumbers:orderJudgment==='disorder-2'}));return{definition,ruleLegal,playableActions,humanTurn,actionable:playableActions.length>0}; }
function showToast(message,tone=''){const toast=$('#toast');toast.textContent=message;toast.className=`toast show ${tone}`;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>{toast.className='toast';},1400);}
function deathRoundProgress(state){const total=state.death?.finalOrder?.length??state.players.length,remaining=state.death?.remaining?.length??0;return{total,current:Math.max(1,total-remaining+1)};}
function renderDeathPresentation(state){const status=$('#death-round-status');if(state.phase!=='deathRound'){if(status)status.hidden=true;document.querySelector('#death-round-overlay')?.remove();return;}const progress=deathRoundProgress(state),actor=playerName(state,state.currentPlayer);if(status){status.hidden=false;status.textContent=`死亡輪 · 最後行動 ${progress.current} / ${progress.total} · ${actor}`;}if(state.death?.presentationAcknowledged||document.querySelector('#death-round-overlay'))return;const overlay=document.createElement('div');overlay.id='death-round-overlay';overlay.className='death-round-overlay';overlay.innerHTML=`<article class="death-round-panel" role="dialog" aria-modal="true" aria-labelledby="death-round-title"><span>本輪終局</span><h2 id="death-round-title">死亡降臨</h2><p>死亡已被揭示。從下一名玩家開始，所有人各取得最後 1 次正常行動。</p><p class="death-round-order">行動順序：${state.death?.finalOrder?.map(id=>playerName(state,id)).join(' → ')??'—'}</p><button type="button">開始最後一圈</button></article>`;overlay.querySelector('button').addEventListener('click',()=>{if(!controller?.state?.death)return;controller.state.death.presentationAcknowledged=true;overlay.remove();controller.prepare();});document.body?.append(overlay);}
function showDetail(card){$('#detail-overlay').hidden=true;resetTagDetailLayout();openCardInspector(card);}
function blindnessPileAction(kind){return actions.find(action=>action.type==='playBlindnessPile'&&action.kind===kind);}
function blindnessPileTitle(kind){return kind==='unknown'?'未知功能牌':names[kind];}
function showBlindnessDetail(kind,count){$('#detail-overlay').classList.remove('tag-detail-overlay');const title=blindnessPileTitle(kind),description=kind==='unknown'?'所有神蹟與災難混在同一個牌堆。拖到中央或在右下角打出時，系統會隨機抽取一張並立即結算其效果。':`這是蒙蔽下的${title}覆蓋牌堆。拖到中央或在右下角打出時，系統會隨機抽取一張${title}並立即結算其效果。`;$('#detail-content').innerHTML=`<div class="blindness-detail-card" aria-label="${title}覆蓋牌">?</div><div class="detail-copy"><span class="eyebrow">審判 · 蒙蔽</span><h2>${title}覆蓋牌 × ${count}</h2><p>${description}</p><p class="detail-note">卡面保持未知；牌堆數量與牌型仍可查看。</p></div>`;$('#detail-overlay').hidden=false;}
function showJudgmentDetail(judgmentId){const judgment=getJudgmentDefinition(judgmentId),active=currentState?.visualQaJudgments?.includes(judgment.id)||currentState?.activeJudgments?.[judgment.domain]===judgment.id,implemented=['disorder-1','disorder-2','sinking-1','blindness-1','blindness-2','overturn-1','overturn-2','division-1','division-2'].includes(judgment.id),status=implemented&&active?(judgment.id==='disorder-2'?'此審判正在生效：克制關係與同類物資的數字大小皆已反轉。':judgment.id==='disorder-1'?'此審判正在生效：物資的克制關係已反轉。':judgment.id==='sinking-1'?'此審判正在生效：單體災難的原目標與其左右相鄰玩家會一同承受效果。':judgment.id==='blindness-1'?'此審判正在生效：神蹟與災難以覆蓋牌堆呈現；選擇牌型後，系統會隨機翻出並打出其中一張。':judgment.id==='blindness-2'?'此審判正在生效：所有神蹟與災難合併為未知功能牌堆，系統會隨機翻出並打出其中一張。':judgment.id==='overturn-2'?'此審判正在生效：神蹟、災難造成的每次手牌／火種變動固定為 1。':judgment.id==='overturn-1'?'此審判正在生效：神蹟、災難造成的每次手牌／火種變動最多為 3。':judgment.id==='division-1'?'此審判正在生效：符合條件時，獲火者以外的最低火種玩家會額外獲得 2 點火種。':'此審判正在生效：符合條件時，最低火種玩家會額外獲得 3 點火種，獲火者也可以被選擇。'):active?'此審判已揭示並保留；實際效果尚未接入。':'這是已被後續審判覆蓋的紀錄。';$('#detail-content').innerHTML=`<div class="judgment-detail"><span class="eyebrow">審判 · ${judgment.domain}</span><h2>${judgment.name}</h2><p class="judgment-effect">${judgment.text}</p><p class="detail-note">${status}</p></div>`;$('#detail-overlay').hidden=false;}
function hideDetail(){$('#detail-overlay').hidden=true;resetTagDetailLayout();closeCardInspector();}
function closeGraceChoice(){gracePending=null;$('#grace-overlay').hidden=true;}
function openGraceChoice(card){const definition=getDefinition(card),playable=actionsForCard(card);gracePending={card,playable};const host=$('#grace-choices');host.replaceChildren();for(const type of RESOURCE_TYPES){const action=playable.find(candidate=>candidate.declaredType===type),button=document.createElement('button');button.className=`grace-choice ${action?'legal-choice':'illegal-choice'}`;button.disabled=!action;button.innerHTML=`<span class="choice-label">${names[type]}</span><span class="choice-card grace-born-preview"><img src="assets/cards/${type}-${definition.number}.png" alt="${names[type]} ${definition.number}"></span><small>${action?'可化為此物資':'目前無法如此化形'}</small>`;if(action)button.addEventListener('click',()=>{closeGraceChoice();selectedInstanceId=null;controller.act(action,token);});host.append(button);}$('#grace-overlay').hidden=false;}
function showDisasterPlayerChoice(card, playable){
  let overlay=document.querySelector('#disaster-player-choice');
  if(!overlay){overlay=document.createElement('div');overlay.id='disaster-player-choice';overlay.hidden=true;document.body.append(overlay);}
  overlay.dataset.decisionCardId=card.instanceId;
  const byPlayer=new Map(playable.filter(action=>action.targetPlayerId).map(action=>[action.targetPlayerId,action]));
  const targets=currentState.players.filter(player=>byPlayer.has(player.playerId));
  selectedInstanceId=null;clearClickPreview();
  renderPlayers(overlay,getDefinition(card).name,'選擇一名其他玩家。',targets,player=>{
    const action=byPlayer.get(player.playerId);overlay.hidden=true;
    if(action)controller.act(action,controller.snapshot());
  },player=>`🔥 ${player.fire}　手牌 ${player.hand.length}`);
}
function playOrChoose(card){const playable=actionsForCard(card),definition=getDefinition(card);if(['disaster-04','disaster-10','disaster-11','disaster-14'].includes(definition.definitionId)&&playable.length&&!playable[0].glassRandom){showDisasterPlayerChoice(card,playable);return;}if(!playable.length){rejectCard(card.instanceId,'這張牌現在無法進入爭局');return;}if(definition.kind==='resource'&&definition.type==='grace'){openGraceChoice(card);return;}selectedInstanceId=null;controller.act(playable[0],token);}
function rejectCard(instanceId,message='目前無法打出'){const el=document.querySelector(`[data-card-id="${CSS.escape(instanceId)}"]`);if(el){el.classList.remove('reject');void el.offsetWidth;el.classList.add('reject');setTimeout(()=>el.classList.remove('reject'),520);}$('#drop-zone').classList.remove('accepting');$('#drop-zone').classList.add('rejecting');setTimeout(()=>$('#drop-zone').classList.remove('rejecting'),420);showToast(message,'warning');}
function dropZoneHit(x,y,startY){const rect=$('#drop-zone').getBoundingClientRect(),direct=x>=rect.left&&x<=rect.right&&y>=rect.top&&y<=rect.bottom,broadCenter=x>innerWidth*.16&&x<innerWidth*.84&&y>innerHeight*.15&&y<innerHeight*.69,fling=y<startY-70&&x>innerWidth*.18&&x<innerWidth*.82;return direct||broadCenter||fling;}
function stopLongPress(){if(drag?.longPressTimer)clearTimeout(drag.longPressTimer);}
function clearClickPreview(except=null){document.querySelectorAll('#hand .card.click-preview,#hand .blindness-pile.click-preview').forEach(card=>{if(card!==except)card.classList.remove('click-preview');});if(!except)selectedBlindnessPile=null;}
