function renderJudgments(state){const host=$('#judgment-bar');if(!host)return;const active=(state.visualQaJudgments??Object.values(state.activeJudgments??{})).map(getJudgmentDefinition);host.replaceChildren(...active.map(judgment=>{const item=document.createElement('button');item.type='button';item.className='judgment-pill';item.title=`短按查看：${judgment.domain}｜${judgment.text}`;item.setAttribute('aria-label',`查看審判 ${judgment.name} 的詳細資訊`);item.textContent=judgment.name;item.addEventListener('click',()=>showJudgmentDetail(judgment.id));return item;}));host.hidden=!active.length;const latest=state.lastJudgment;if(latest&&latest.judgmentId!==lastJudgmentId){lastJudgmentId=latest.judgmentId;const judgment=getJudgmentDefinition(latest.judgmentId),replaced=latest.replacedJudgmentId?`，覆蓋 ${getJudgmentDefinition(latest.replacedJudgmentId).name}`:'';showToast(`審判降臨：${judgment.name}${replaced}`,'warning');}}
// Keep the visual fill independent of the game state, including threshold overflow.
let corruptionJudgmentCount = null, corruptionFillTimer = null, corruptionFillTarget = 0;
function renderCorruptionFill(state, value) {
  const hud = $('.corruption-hud');
  if (!hud?.style?.setProperty) return;
  const threshold = Number.isFinite(state.corruptionThreshold) && state.corruptionThreshold > 0 ? state.corruptionThreshold : 30;
  const percentage = Math.max(0, Math.min(100, value / threshold * 100));
  const count = state.judgmentHistory?.length ?? 0;
  corruptionFillTarget = percentage;
  if (corruptionJudgmentCount !== null && count > corruptionJudgmentCount) {
    clearTimeout(corruptionFillTimer);
    hud.style.setProperty('--corruption-fill', '100%');
    corruptionFillTimer = setTimeout(() => {
      hud.classList.add('corruption-reset');
      hud.style.setProperty('--corruption-fill', '0%');
      requestAnimationFrame(() => requestAnimationFrame(() => {
        hud.classList.remove('corruption-reset');
        hud.style.setProperty('--corruption-fill', `${corruptionFillTarget}%`);
        corruptionFillTimer = null;
      }));
    }, 800);
  } else if (count < (corruptionJudgmentCount ?? count)) {
    clearTimeout(corruptionFillTimer);
    corruptionFillTimer = null;
    hud.style.setProperty('--corruption-fill', `${percentage}%`);
  } else if (!corruptionFillTimer) {
    hud.style.setProperty('--corruption-fill', `${percentage}%`);
  }
  corruptionJudgmentCount = count;
}
